        fun dfs(node: TreeNode?, depth: Int) {
            if (node == null) return
            if (depth == result.size) result.add(mutableListOf())
            result[depth].add(node.`val`)
            dfs(node.left, depth + 1)
            dfs(node.right, depth + 1)
        }
        dfs(root, 0)
